<script setup lang="ts">
import {nodeDisplayName} from '../nodePresentation'
import {downloadGroup,serviceAvailability} from '../sharedResults'
import {attemptTone,serviceConclusion} from '../measurementRounds'
import UiSelect from './UiSelect.vue'
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {api,saveFile} from '../api'
import {useWorkspace} from '../workspace'
import {bytes,date,downloadSpeed,downloadTone,latencyFor,key,median,outcomeLabel,outcomeTone,sampleFor,scope,stateLabel,targets,type Attempt,type HistoryPage,type LatencyTest,type NodeOption,type Project,type MonitorSample} from '../domain'
import {attemptStatus,downloadCondition,downloadConditionLabel,triggerLabel} from '../measurementRounds'
import {manualLatencyPoint,latencyPointLabel,latencySampleState,monitorLatencyPoints,monitorRoundPoints,monitorHTTPPoints,monitorHTTPServices,type TrendPoint} from '../presentation'
import Icon from './Icon.vue'
import Modal from './Modal.vue'
import TrendChart from './TrendChart.vue'
const props=defineProps<{node:NodeOption}>(),emit=defineEmits<{close:[]}>(),w=useWorkspace(),project=ref<Exclude<Project,'combined'>>(w.project.value==='combined'?'latency':w.project.value),target=ref(w.displayTarget.value),serviceId=ref(w.serviceIds.value[0]||''),tests=ref<LatencyTest[]>([]),attempts=ref<Attempt[]>([]),loading=ref(false),error=ref(''),more=ref(false),raw=ref(false),samplePage=ref(1),revisions=ref<{config_revision_key:string;node_key:string;display_name:string;last_observed_at?:string}[]>([]),revision=ref(props.node.config_revision_key),record=ref<Attempt|null>(null)
const source=ref<'manual'|'monitor'>(w.page.value==='monitor'?'monitor':'manual'),monitorProbe=ref('monitor_google_http'),monitorSamples=ref<MonitorSample[]>([]),monitorCursor=ref('')
if(source.value==='monitor'&&project.value==='download')project.value='latency'
let version=0,revisionVersion=0;const until=ref(new Date().toISOString()),since=computed(()=>new Date(Date.parse(until.value)-w.hours.value*3600000).toISOString())
const nodeScope=computed(()=>({...props.node,config_revision_key:revision.value,node_key:revisions.value.find(r=>r.config_revision_key===revision.value)?.node_key||props.node.node_key}))
async function load(append=false){const token=++version;loading.value=true;error.value='';if(!append){tests.value=[];attempts.value=[];monitorSamples.value=[];monitorCursor.value='';more.value=false}try{
if(source.value==='monitor'){const probe=project.value==='service'?monitorHTTPServices.find(p=>p.id===monitorProbe.value):{probeType:'rtt',target:undefined};if(!probe)return;const n={...nodeScope.value};const result=await api.monitorSamples({profile_id:n.profile_id,node_identity_key:n.node_identity_key,config_revision_key:n.config_revision_key,probe_type:probe.probeType,target:probe.target,since:since.value,until:until.value,cursor:append?monitorCursor.value:undefined,limit:project.value==='latency'?300:50,order_desc:true});if(token!==version)return;monitorSamples.value=append?[...monitorSamples.value,...(result.items||[])]:result.items||[];monitorCursor.value=result.next_cursor;more.value=result.has_more;return}
const last=project.value==='latency'?tests.value[tests.value.length-1]:attempts.value[attempts.value.length-1];const extra:Record<string,unknown>={since:since.value,until:until.value,limit:50};if(append&&last){extra.before_attempt_id=last.attempt_id;extra[project.value==='latency'?'before_finished_at':'before_at']=project.value==='latency'?(last as LatencyTest).finished_at:last.finished_at||last.requested_at}if(project.value==='service'&&serviceId.value)extra.service_id=serviceId.value;const result=project.value==='latency'?await api.latencyHistory(nodeScope.value,extra):await api.attemptHistory(project.value,nodeScope.value,extra);if(token!==version)return;more.value=result.has_more;if(project.value==='latency'){const items=(result as HistoryPage<LatencyTest>).tests||[];tests.value=append?[...tests.value,...items]:items;if(revision.value===props.node.config_revision_key)items.forEach(w.mergeLatency)}else{const items=(result as HistoryPage<Attempt>).attempts||[];attempts.value=append?[...attempts.value,...items]:items;if(revision.value===props.node.config_revision_key)items.forEach(a=>w.mergeAttempt(project.value as 'download'|'service',a))}}catch(e){if(token===version)error.value=e instanceof Error?e.message:String(e)}finally{if(token===version)loading.value=false}}
watch(source,()=>{if(source.value==='monitor'&&project.value==='download')project.value='latency'})
watch([source,monitorProbe,project,serviceId,revision,()=>props.node,()=>w.hours.value],()=>{tests.value=[];attempts.value=[];samplePage.value=1;record.value=null;until.value=new Date().toISOString();void load()},{immediate:true})
watch(()=>props.node,async n=>{const token=++revisionVersion;revision.value=n.config_revision_key;revisions.value=[];try{const result=await api.revisions(n);if(token===revisionVersion)revisions.value=result||[]}catch{}},{immediate:true})
onBeforeUnmount(()=>{version++;revisionVersion++})
const chartPoints=computed<TrendPoint[]>(()=>{
 if(source.value==='monitor')return project.value==='service'?monitorHTTPPoints(monitorSamples.value,monitorProbe.value):monitorLatencyPoints(monitorSamples.value,target.value)
 if(project.value==='latency')return tests.value.slice().reverse().map(t=>manualLatencyPoint(t,target.value))
 return attempts.value.slice().reverse().map(a=>{
  const value=project.value==='download'?downloadSpeed(a):serviceAvailability(a),tone=project.value==='download'?downloadTone(a):attemptTone(a)
  return {id:a.attempt_id,time:a.finished_at||a.requested_at,value,tone:project.value==='service'&&value===null&&tone==='bad'?'warn':tone,conditionKey:project.value==='download'?downloadGroup(a).key:undefined,description:`${date(a.finished_at||a.requested_at)} · ${triggerLabel(a.trigger_type)} · 轮次 ${a.round_id||'关联未知'} · ${project.value==='download'?outcomeLabel(a.result?.outcome):serviceConclusion(a)}${project.value==='download'?' · '+downloadConditionLabel(a):''}`}
 })
})
const samples=computed(()=>tests.value.flatMap(t=>t.samples.map(s=>({...s,...latencySampleState(s),attempt_id:t.attempt_id}))).sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp))),sampleSlice=computed(()=>samples.value.slice((samplePage.value-1)*50,samplePage.value*50))
const siteStats=computed(()=>targets.map(t=>{const list=tests.value.flatMap(test=>sampleFor(test,t.id)),successful=list.filter(s=>s.success);return {...t,value:median(successful.map(s=>s.latency_ms)),success:successful.length,total:list.length}}))
async function retry(a:Attempt){const token=version,kind=project.value as 'download'|'service',n={...nodeScope.value};try{const saved=await api.attemptAction(kind,a.attempt_id,n,'retry-save',a.service_id);if(token!==version)return;record.value=saved;await load()}catch(e){if(token===version)error.value=e instanceof Error?e.message:String(e)}}
</script>
<template><Modal :title="nodeDisplayName(node)" wide @close="emit('close')"><div class="detail-context"><span>{{node.profile_name}} · {{node.type}}</span><button class="text-button" :disabled="w.busy.value" @click="w.openPlan([node]);emit('close')"><Icon name="play"/>检测此节点</button><button class="text-button" @click="w.monitorNodes.value=[{...node}];emit('close')">加入持续监测</button></div><nav class="view-switch" aria-label="节点记录来源"><button :aria-pressed="source==='manual'" @click="source='manual'">工作台记录</button><button :aria-pressed="source==='monitor'" @click="source='monitor'">持续监测</button></nav><nav class="project-tabs"><button v-for="p in (['latency','download','service'] as Exclude<Project,'combined'>[])" :key="p" :aria-selected="project===p" :disabled="source==='monitor'&&p==='download'" @click="project=p">{{p==='latency'?'延迟':p==='download'?'下载':'服务'}}</button></nav><div class="detail-filters"><label v-if="project==='latency'">站点<UiSelect v-model="target"><option v-for="t in targets" :key="t.id" :value="t.id">{{t.name}}</option></UiSelect></label><label v-if="source==='manual'&&project==='service'">服务<UiSelect v-model="serviceId"><option value="">全部服务</option><option v-for="s in w.catalog.value" :key="s.service_id" :value="s.service_id">{{s.name}}</option></UiSelect></label><label v-if="source==='monitor'&&project==='service'">监测服务<UiSelect v-model="monitorProbe" aria-label="节点监测服务"><option v-for="p in monitorHTTPServices" :key="p.id" :value="p.id">{{p.name}}</option></UiSelect></label><span v-if="source==='monitor'&&project==='latency'" class="muted small">持续监测 · {{targets.find(t=>t.id===target)?.name}}</span><label>范围<UiSelect v-model.number="w.hours.value"><option :value="6">最近 6 小时</option><option :value="24">最近 24 小时</option><option :value="168">最近 7 天</option><option :value="720">最近 30 天</option></UiSelect></label><label v-if="revisions.length>1">配置版本<UiSelect v-model="revision"><option :value="node.config_revision_key">当前配置</option><option v-for="r in revisions.filter(r=>r.config_revision_key!==node.config_revision_key)" :key="r.config_revision_key" :value="r.config_revision_key">{{nodeDisplayName(r)}} · {{r.config_revision_key.slice(-8)}}</option></UiSelect></label><button class="button ghost" @click="until=new Date().toISOString();load()"><Icon name="refresh"/>刷新</button></div><p v-if="source==='monitor'&&project==='service'" class="muted small">基础 HTTP：响应 2xx／3xx 记为成功，不代表解锁或工作台的严格服务规则通过。</p><p v-if="error" class="inline-error" role="alert">{{error}}</p><div v-if="loading&&!chartPoints.length" class="loading-state">读取记录中…</div><template v-else><div v-if="source==='manual'&&project==='latency'" class="site-stat-grid"><button v-for="s in siteStats" :key="s.id" :class="{active:target===s.id}" @click="target=s.id"><small>{{s.name}}</small><strong>{{s.value===null?'—':`${s.value.toFixed(0)} ms`}}</strong><span>{{s.total?`${s.success}/${s.total} 样本成功`:'未检测'}}</span></button></div><p v-if="source==='manual'&&project==='latency'" class="small muted">上方汇总仅描述已读样本；跨轮方法或出口可能不同，不能据此直接比较节点。各轮条件见“方法与出口”。</p><TrendChart v-if="source==='monitor'||project!=='service'||serviceId" :points="chartPoints" :unit="project==='latency'?'ms':project==='download'?'MiB/s':'通过'" label="所选节点检测历史"/><p v-if="more" class="muted small">当前显示部分历史，统计仅涵盖已读取的记录。</p><div class="detail-table-tools"><strong>{{source==='monitor'?'持续监测样本':project==='latency'?raw?'原始样本':'检测记录':'检测记录'}}</strong><button v-if="source==='manual'&&project==='latency'" class="text-button" @click="raw=!raw">{{raw?'查看检测轮次':'查看原始样本'}}</button><button class="text-button" @click="saveFile(JSON.stringify(source==='monitor'?monitorSamples:project==='latency'?tests:attempts,null,2),'speedtest-node-history.json','application/json').then(saved=>{if(saved)w.notify('记录已导出')}).catch(w.fail)">导出记录</button></div><div class="table-scroll"><table v-if="source==='monitor'"><thead><tr><th>时间</th><th>目标</th><th>{{project==='latency'?'延迟':'HTTP 结果'}}</th><th>结果</th></tr></thead><tbody><tr v-for="s in monitorSamples" :key="s.sample_id"><td>{{date(s.timestamp)}}<small v-if="s.metadata?.competing_probes?.length" class="warn">并发竞争：{{s.metadata.competing_probes.join('、')}} · 不宜单独判断节点质量</small></td><td class="break-text">{{s.target}}</td><td>{{project==='latency'?(s.success?`${(s.latency/1e6).toFixed(0)} ms`:'—'):s.success?'HTTP 可达':'失败'}}</td><td :class="s.error_class==='not_executed'?'empty':s.success?(s.error_detail?'warn':'good'):'bad'">{{s.success?'成功':s.error_class||'失败'}}<small v-if="s.error_detail">{{s.error_detail}}</small></td></tr></tbody></table><table v-else-if="project==='latency'&&!raw"><thead><tr><th>完成时间</th><th>所选站点</th><th>成功 / 样本</th><th>保存状态</th></tr></thead><tbody><tr v-for="t in tests" :key="t.attempt_id"><td>{{date(t.finished_at)}}</td><td>{{latencyPointLabel(manualLatencyPoint(t,target),target)}}<details class="small"><summary>方法与出口</summary><p>{{t.source||'来源未知'}} · {{t.method||'方法未知'}} / v{{t.method_version||'?'}} · {{t.attempt_id}}</p><pre>{{JSON.stringify(t.network_path||{evidence:'旧结果无出口证据'},null,2)}}</pre></details></td><td>{{sampleFor(t,target).filter(s=>s.success).length}} / {{sampleFor(t,target).length}}<small v-if="t.status==='not_executed'" class="muted">未执行 · {{t.error_message||t.network_path?.failure_reason||'原因未记录'}}</small></td><td><span :class="t.persistence_state==='failed'?'bad':''">{{stateLabel(t.persistence_state)}}</span><small v-if="t.persistence_error">{{t.persistence_error}}</small></td></tr></tbody></table><table v-else-if="project==='latency'"><thead><tr><th>时间</th><th>目标</th><th>延迟</th><th>结果</th></tr></thead><tbody><tr v-for="s in sampleSlice" :key="s.attempt_id+s.seq+s.target"><td>{{date(s.timestamp)}}</td><td class="break-text">{{s.target||'旧版 Cloudflare'}}</td><td>{{s.success?`${s.latency_ms} ms`:'—'}}</td><td :class="s.tone">{{s.executionState==='cancelled'?'已取消':s.success?'成功':s.error||'失败'}}<small v-if="s.executionState==='cancelled'">{{s.error}}</small></td></tr></tbody></table><table v-else><thead><tr><th>时间</th><th>{{project==='download'?'下载速度':'服务'}}</th><th>结果</th><th>保存</th><th/></tr></thead><tbody><tr v-for="a in attempts" :key="a.attempt_id"><td>{{date(a.finished_at||a.requested_at)}}</td><td>{{project==='download'?downloadSpeed(a)===null?'—':`${downloadSpeed(a)?.toFixed(2)} MiB/s`:a.rule.name||a.service_id}}</td><td><span :class="project==='download'?downloadTone(a):a.result?outcomeTone(a.result.outcome):''">{{attemptStatus(a,project==='download')}}</span><small v-if="project==='download'">{{bytes(a.result?.bytes_read)}}</small></td><td>{{stateLabel(a.persistence_state)}}</td><td><button class="text-button" @click="record=record?.attempt_id===a.attempt_id?null:a">详情</button></td></tr></tbody></table></div><div v-if="source==='manual'&&raw&&project==='latency'" class="pagination"><button class="button ghost" :disabled="samplePage<=1" @click="samplePage--">上一页</button>{{samplePage}} / {{Math.max(1,Math.ceil(samples.length/50))}}<button class="button ghost" :disabled="samplePage*50>=samples.length" @click="samplePage++">下一页</button></div><div v-if="record" class="measurement-detail"><h3>{{record.rule.name||'下载测量详情'}}</h3><p>{{record.result?.summary||record.result?.error_message||stateLabel(record.execution_state)}}</p><p v-if="record.result?.competing_probes?.length||record.result?.details?.competing_probes" class="inline-warning">检测时有并发探测竞争：{{record.result.competing_probes?.join('、')||record.result.details?.competing_probes}}。本次延迟或速度下降不能单独归因于节点。</p><p class="small muted break-text">目标：{{record.rule.target_url}}</p><p v-if="record.rule.success_criterion" class="small muted">判断依据：{{record.rule.success_criterion}}</p><p v-if="record.persistence_error" class="inline-error">{{record.persistence_error}}<button v-if="record.persistence_state==='failed'&&record.result" class="text-button" @click="retry(record!)">重试保存</button></p><details v-if="record.result?.details"><summary>详细返回信息</summary><pre>{{JSON.stringify(record.result.details,null,2)}}</pre></details><details v-if="record.result?.samples?.length"><summary>下载采样 · {{record.result.samples.length}} 条</summary><table><thead><tr><th>已持续</th><th>瞬时速度</th><th>累计数据</th></tr></thead><tbody><tr v-for="(s,i) in record.result.samples" :key="i"><td>{{(s.elapsed_ns/1e9).toFixed(1)}} 秒</td><td>{{s.speed_mbps===undefined?'—':(s.speed_mbps/8).toFixed(2)}} MB/s</td><td>{{bytes(s.cumulative_bytes)}}</td></tr></tbody></table></details></div><button v-if="more" class="button" :disabled="loading" @click="load(true)">{{loading?'读取中…':'读取更早记录'}}</button><p v-if="!loading&&!error&&!chartPoints.length" class="muted">当前范围没有记录；你可以扩大历史范围或开始检测。</p></template></Modal></template>
